    #[cfg_attr(all(kani, kani_smallsort_sorting), kani::requires(v.len() <= <T as UnstableSmallSortTypeImpl>::small_sort_threshold()))]
    #[cfg_attr(all(kani, kani_smallsort_sorting), kani::modifies(v))]
