//! Stable scratch geometry and full-value preservation with an arbitrary reading comparator.
//! The unwind budget accommodates the selected route and its full-value count loops.

use super::super::{SMALL_SORT_GENERAL_THRESHOLD, StableSmallSortTypeImpl};
use super::merge::{probe_count_unrolled, regions_are_disjoint, set_value_probe};
use crate::mem::MaybeUninit;
use crate::slice::sort::shared::FreezeMarker;
use crate::{kani, ptr};

fn require_freeze<T: FreezeMarker>() {}

fn arbitrary_order(a: &u64, b: &u64) -> bool {
    // SAFETY: the sort must provide initialized, readable elements for both references.
    unsafe {
        ptr::read_volatile(a);
        ptr::read_volatile(b);
    }
    kani::any()
}

fn abort_on_order_violation() -> ! {
    kani::assume(false);
    unreachable!()
}

fn check_geometry<const N: usize>(
    original: &[u64; N],
    v: &mut [u64],
    scratch: &mut [MaybeUninit<u64>],
) {
    const { assert!(N >= 2 && N <= 32) };
    require_freeze::<u64>();
    let threshold = <u64 as StableSmallSortTypeImpl>::small_sort_threshold();
    assert!(threshold == SMALL_SORT_GENERAL_THRESHOLD);
    assert!(v.len() == N && N <= threshold);
    assert!(scratch.len() >= N + 16);
    assert!(regions_are_disjoint::<u64>(
        v.as_ptr(),
        N,
        scratch.as_ptr().cast::<u64>(),
        scratch.len(),
    ));
    // Stable's Freeze specialization calls small_sort_general_with_scratch unconditionally;
    // the efficient-swap predicate belongs to unstable dispatch and is not a stable selector.
    kani::cover(
        threshold == SMALL_SORT_GENERAL_THRESHOLD && v.len() >= 2,
        "Stable Freeze selects small_sort_general_with_scratch beyond its early return",
    );
    set_value_probe::<u64>();
    <u64 as StableSmallSortTypeImpl>::small_sort(v, scratch, &mut arbitrary_order);
    // u64 has no padding: the existing arbitrary byte probe observes the complete value.
    // Both regions counted here contain N initialized u64 values; scratch is never counted.
    assert!(
        probe_count_unrolled::<u64>(original.as_ptr(), N)
            == probe_count_unrolled::<u64>(v.as_ptr(), N),
        "full u64 value multiplicities are preserved on normal return"
    );
    kani::cover(true, "scratch geometry returns normally and preserves full values");
}

fn separate_allocation<const N: usize, const S: usize>() {
    const { assert!(S >= N + 16 && S != 48) };
    let original: [u64; N] = kani::any();
    let mut v = original;
    let mut scratch = [MaybeUninit::<u64>::uninit(); S];
    assert!(!kani::mem::same_allocation(v.as_ptr(), scratch.as_ptr().cast::<u64>()));
    check_geometry(&original, &mut v, &mut scratch);
}

macro_rules! geometry_harness {
    ($name:ident, $body:ident, $n:literal, $capacity:literal) => {
        #[kani::proof]
        #[kani::stub(super::super::panic_on_ord_violation, abort_on_order_violation)]
        #[kani::unwind(34)]
        fn $name() {
            $body::<$n, $capacity>();
        }
    };
}

geometry_harness!(stable_u64_min_scratch_n2, separate_allocation, 2, 18);

//! Smoke checks cover the in-place swap size heuristic.
//! The type matrix includes scalars, arrays around the size threshold, `Cell`, Drop, and ZSTs.

use super::super::has_efficient_in_place_swap;
use crate::kani;
#[repr(transparent)]
struct SwapDrop(u8);

impl crate::ops::Drop for SwapDrop {
    fn drop(&mut self) {}
}

/// Checks the heuristic for scalar, array, `Cell`, Drop, and zero-sized element types.
#[kani::proof]
fn predicate_efficient_swap_type_matrix() {
    macro_rules! check {
        ($t:ty, $expected:literal) => {
            assert!(has_efficient_in_place_swap::<$t>() == $expected);
            kani::cover(true, concat!("efficient swap predicate for ", stringify!($t)));
        };
    }
    check!(u8, true);
    check!(u16, true);
    check!(u64, true);
    check!(u128, false);
    check!([u8; 9], false);
    check!([u8; 16], false);
    check!([u8; 17], false);
    check!([u8; 85], false);
    check!([u8; 86], false);
    check!(SwapDrop, true);
    check!(crate::cell::Cell<i32>, true);
    check!((), true);
}

//! Bounded permutation checks with distinct identity tags and arbitrary comparison answers.
//!
//! Each comparison reads both arguments and chooses a fresh bool. No ordering law is assumed.
//! Distinct tags track equal payloads separately, and fresh answers include every answer
//! sequence of a returning comparator. The fixed initial identity order restricts no payload
//! order; see verify.rs for the whole-element transfer assumption and its limits.
//! Tag types match the source types without wrappers; a separate root checks dispatch.
//!
//! Exactly N outputs, range checks, and an all-ones mask imply that each tag occurs once.
//! A u64 mask accommodates 32 tags without a full-width shift. The unwind budget also covers
//! the largest selected route and the tag-check loops.

use super::super::{
    MAX_STACK_ARRAY_SIZE, SMALL_SORT_FALLBACK_THRESHOLD, SMALL_SORT_GENERAL_SCRATCH_LEN,
    SMALL_SORT_GENERAL_THRESHOLD, SMALL_SORT_NETWORK_SCRATCH_LEN, SMALL_SORT_NETWORK_THRESHOLD,
    StableSmallSortTypeImpl, UnstableSmallSortFreezeTypeImpl, UnstableSmallSortTypeImpl,
    has_efficient_in_place_swap,
};
use crate::cell::Cell;
use crate::mem::size_of;
use crate::{kani, ptr};

fn arbitrary_u8_order(a: &u8, b: &u8) -> bool {
    // SAFETY: the real sort must supply initialized, readable comparator arguments.
    unsafe {
        let _ = ptr::read_volatile(a);
        let _ = ptr::read_volatile(b);
    }
    kani::any()
}

#[cfg(kani_smallsort_controls)]
fn abort_on_order_violation() -> ! {
    kani::cover(true, "order violation panic is reachable");
    kani::assume(false);
    unreachable!()
}

// The ordinary networks never reach this panic boundary. Keep the cutoff but omit its cover.
fn abort_without_panic_cover() -> ! {
    kani::assume(false);
    unreachable!()
}

fn check_tags<const N: usize>(tags: &[u64; N]) {
    assert!(N > 0 && N <= 32);
    let mut seen = 0u64;
    for &tag in tags {
        kani::assert(tag < N as u64, "output tag is in range");
        // Keep the shift defined even on a counterexample with an out-of-range tag.
        if tag < N as u64 {
            seen |= 1u64 << tag;
        }
    }
    kani::assert(seen == (1u64 << N) - 1, "every input tag occurs exactly once");
}

fn network_output<const N: usize>() -> [u8; N] {
    let mut v = crate::array::from_fn(|i| i as u8);
    <u8 as UnstableSmallSortTypeImpl>::small_sort(&mut v, &mut arbitrary_u8_order);
    v
}

fn network_body<const N: usize>() {
    let v = network_output::<N>();
    check_tags(&crate::array::from_fn::<_, N, _>(|i| v[i] as u64));
    kani::cover(true, "network returns with every tag");
}

#[kani::proof]
fn tag_types_preserve_source_routes() {
    fn require_freeze_copy<T: crate::slice::sort::shared::FreezeMarker + Copy>() {}
    require_freeze_copy::<u8>();
    require_freeze_copy::<u64>();

    // Unstable u8 takes the Freeze+Copy network specialization and its size branch.
    assert!(size_of::<u8>() == 1);
    assert!(has_efficient_in_place_swap::<u8>());
    assert!(size_of::<u8>() * SMALL_SORT_NETWORK_SCRATCH_LEN <= MAX_STACK_ARRAY_SIZE);
    assert!(<u8 as UnstableSmallSortTypeImpl>::small_sort_threshold() == 32);
    assert!(
        <u8 as UnstableSmallSortFreezeTypeImpl>::small_sort_threshold()
            == SMALL_SORT_NETWORK_THRESHOLD
    );

    // Stable Freeze u64 always selects general, independently of the swap heuristic.
    assert!(size_of::<u64>() == 8);
    assert!(SMALL_SORT_GENERAL_SCRATCH_LEN == 48);
    assert!(
        <u64 as StableSmallSortTypeImpl>::small_sort_threshold() == SMALL_SORT_GENERAL_THRESHOLD
    );
    assert!(SMALL_SORT_GENERAL_THRESHOLD == 32);

    // The Freeze specialization would return 32: 16 identifies the blanket Stable entry.
    assert!(
        <Cell<u8> as StableSmallSortTypeImpl>::small_sort_threshold()
            == SMALL_SORT_FALLBACK_THRESHOLD
    );
    assert!(SMALL_SORT_FALLBACK_THRESHOLD == 16);
    kani::cover(true, "tag and source types select the required routes");
}

#[kani::proof]
#[kani::stub(
    crate::slice::sort::shared::smallsort::panic_on_ord_violation,
    abort_without_panic_cover
)]
#[kani::unwind(34)]
fn network_u8_n9() {
    network_body::<9>();
}

#[kani::proof]
#[kani::stub(
    crate::slice::sort::shared::smallsort::panic_on_ord_violation,
    abort_without_panic_cover
