    <Cell<u8> as StableSmallSortTypeImpl>::small_sort(
        &mut v, &mut scratch, &mut KeyLess::<Cell<u8>>::new());
    assert!(post::<Cell<u8>, KeyLess<Cell<u8>>>(before, &v), "S1_DEFAULT_COMPANION_POST");
    kani::cover(true, "S1_actual_default_companion_return");
}

#[kani::proof_for_contract(<u8 as StableSmallSortTypeImpl>::small_sort)]
#[kani::unwind(34)]
fn stable_freeze_activation() {
    let mut v = [2u8, 1u8];
    assert!(enabled::<u8, KeyLess<u8>>(), "S1_ACTUAL_OVERRIDE_ENABLED");
    let before = snapshot::<u8, KeyLess<u8>>(&v);
    let mut scratch: [MaybeUninit<u8>; 18] = [MaybeUninit::uninit(); 18];
    <u8 as StableSmallSortTypeImpl>::small_sort(
        &mut v, &mut scratch, &mut KeyLess::<u8>::new());
    assert!(post::<u8, KeyLess<u8>>(before, &v), "S1_OVERRIDE_COMPANION_POST");
    kani::cover(true, "S1_actual_override_companion_return");
}

//! S2 proposal: exact full-byte transfer for the actual swap_if_less contract.
//! Register under kani_smallsort_sorting only after integration of the attrs in
//! the W11 S2 INTERFACE. This module does not attach a contract by itself.
//! Only u8/KeyLess<u8> is active here; S1's other pairs are not swap-qualified.

use super::sorting_model::KeyLess;

#[derive(Clone, Copy)]
pub(in crate::slice::sort::shared::smallsort) struct PairSnapshot {
    a: u8,
    b: u8,
    valid: bool,
}

impl PairSnapshot {
    fn invalid() -> Self { Self { a: 0, b: 0, valid: false } }
}

trait SwapModel<T, F> {
    fn enabled() -> bool;
    fn capture(base: *const T, a: usize, b: usize) -> PairSnapshot;
    fn post(pre: PairSnapshot, base: *const T, a: usize, b: usize) -> bool;
}

impl<T, F> SwapModel<T, F> for () {
    default fn enabled() -> bool { false }
    default fn capture(_base: *const T, _a: usize, _b: usize) -> PairSnapshot {
        PairSnapshot::invalid()
    }
    default fn post(_pre: PairSnapshot, _base: *const T, _a: usize, _b: usize) -> bool {
        true
    }
}

impl SwapModel<u8, KeyLess<u8>> for () {
    fn enabled() -> bool { true }
    fn capture(base: *const u8, a: usize, b: usize) -> PairSnapshot {
        // SAFETY: the actual callee's existing requires establish both initialized,
        // readable positions, nonwrapping offsets and a common allocation first.
        unsafe { PairSnapshot { a: *base.add(a), b: *base.add(b), valid: true } }
    }
    fn post(pre: PairSnapshot, base: *const u8, a: usize, b: usize) -> bool {
        if !pre.valid { return false; }
        let now = <() as SwapModel<u8, KeyLess<u8>>>::capture(base, a, b);
        if pre.b < pre.a {
            now.a == pre.b && now.b == pre.a
        } else {
            now.a == pre.a && now.b == pre.b
        }
    }
}

/// Unconditional generic facade; no new T/F bounds on the actual helper.
pub(in crate::slice::sort::shared::smallsort) fn enabled<T, F>() -> bool {
    <() as SwapModel<T, F>>::enabled()
}

/// Spec-only read: active callers must establish the actual swap requires first.
/// Inactive calls do not inspect pointers, indices or pointed-to bytes.
pub(in crate::slice::sort::shared::smallsort) fn capture<T, F>(
    base: *const T, a: usize, b: usize,
) -> PairSnapshot {
    <() as SwapModel<T, F>>::capture(base, a, b)
}

/// Exact conditional transfer implies pair order and preservation of both full
/// bytes, including equal positions. The actual modifies clause supplies frame.
pub(in crate::slice::sort::shared::smallsort) fn post<T, F>(
    pre: PairSnapshot, base: *const T, a: usize, b: usize,
) -> bool {
    <() as SwapModel<T, F>>::post(pre, base, a, b)
}

//! Opt-in DIAGNOSTIC_ASSUMED spec predicates; no qualified semantic leaves.
//! Active only for u8/default KeyLess. Inactive specialization never reads storage.
use super::sorting_model::{self, KeyLess, Snapshot};
use crate::slice;
trait Span<T, F> {
    fn active() -> bool;
    fn capture(p: *const T, n: usize) -> Snapshot;
    fn post(s: Snapshot, p: *const T, n: usize) -> bool;
    fn ordered(p: *const T, n: usize) -> bool;
}
impl<T, F> Span<T, F> for () {
    default fn active() -> bool { false }
    default fn capture(_p: *const T, _n: usize) -> Snapshot {
        sorting_model::snapshot::<u8, ()>(&[])
    }
    default fn post(_s: Snapshot, _p: *const T, _n: usize) -> bool { true }
    default fn ordered(_p: *const T, _n: usize) -> bool { true }
}
impl Span<u8, KeyLess<u8>> for () {
    fn active() -> bool { true }
    fn capture(p: *const u8, n: usize) -> Snapshot {
        if n > 32 { return sorting_model::snapshot::<u8, ()>(&[]); }
        if n == 0 { return sorting_model::snapshot::<u8, KeyLess<u8>>(&[]); }
        // SAFETY: requires establishes initialized readable n-span before spec read.
        unsafe { sorting_model::snapshot::<u8, KeyLess<u8>>(slice::from_raw_parts(p, n)) }
    }
    fn post(s: Snapshot, p: *const u8, n: usize) -> bool {
        if n > 32 { return false; }
        if n == 0 { return sorting_model::post::<u8, KeyLess<u8>>(s, &[]); }
        unsafe { sorting_model::post::<u8, KeyLess<u8>>(s, slice::from_raw_parts(p, n)) }
    }
    fn ordered(p: *const u8, n: usize) -> bool {
        if n > 32 { return false; }
        let mut i = 1;
        while i < n {
            if unsafe { *p.add(i) < *p.add(i - 1) } { return false; }
            i += 1;
        }
        true
    }
}
pub(in crate::slice::sort::shared::smallsort) fn active<T, F>() -> bool {
    <() as Span<T,F>>::active()
}
pub(in crate::slice::sort::shared::smallsort) fn capture<T, F>(p: *const T,n: usize) -> Snapshot {
    <() as Span<T,F>>::capture(p,n)
}
pub(in crate::slice::sort::shared::smallsort) fn post<T, F>(s: Snapshot,p: *const T,n: usize) -> bool {
    <() as Span<T,F>>::post(s,p,n)
}
pub(in crate::slice::sort::shared::smallsort) fn ordered<T, F>(p: *const T,n: usize) -> bool {
    <() as Span<T,F>>::ordered(p,n)
}
